import json


def parse_script(text: str) -> dict:
    """Parse a dialogue script into a structured graph with nodes and edges."""
    nodes = {}   # id -> node dict
    edges = []   # list of edge dicts

    # Split into sections: each section starts with [NodeName] on its own line
    sections = re.split(r'\n(?=\[)', text.strip())

    for section in sections:
        lines = section.strip().split('\n')
        header = lines[0].strip()
        if not header.startswith('[') or not header.endswith(']'):
            continue

        node_id = header[1:-1]

        content_lines = [l.strip() for l in lines[1:] if l.strip()]
        if not content_lines:
            continue

        first = content_lines[0]

        if re.match(r'^\d+\.', first):
            # Choice node: "N. [optional tag] text -> target"
            if node_id not in nodes:
                nodes[node_id] = {
                    "id": node_id,
                    "text": "",
                    "speaker": "",
                    "type": "choice"
                }

            for line in content_lines:
                m = re.match(r'^\d+\.\s+(.+?)\s*->\s*(.+)$', line)
                if m:
                    choice_text = m.group(1).strip()
                    target = m.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": choice_text
                    })
        else:
            # Line node: "Speaker: dialogue text -> target"
            m = re.match(r'^(.+?):\s+(.+?)\s*->\s*(.+)$', first)
            if m:
                speaker = m.group(1).strip()
                dialogue = m.group(2).strip()
                target = m.group(3).strip()

                nodes[node_id] = {
                    "id": node_id,
                    "text": dialogue,
                    "speaker": speaker,
                    "type": "line"
                }

                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })

    # Ensure target nodes referenced in edges exist (e.g. "End")
    all_targets = {e["to"] for e in edges}
    for target_id in all_targets:
        if target_id not in nodes:
            nodes[target_id] = {
                "id": target_id,
                "text": "",
                "speaker": "",
                "type": "line"
            }

    return {"nodes": list(nodes.values()), "edges": edges}


if __name__ == "__main__":
    with open("/app/script.txt", "r") as f:
        content = f.read()

    graph = parse_script(content)

    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    print(f"Parsed {len(graph['nodes'])} nodes and {len(graph['edges'])} edges")

    # Build adjacency list for reachability check
    adj = {}
    for n in graph["nodes"]:
        adj[n["id"]] = []
    for e in graph["edges"]:
        if e["from"] in adj:
            adj[e["from"]].append(e["to"])

    # BFS from first node
    first_id = graph["nodes"][0]["id"] if graph["nodes"] else None
    reachable = set()
    if first_id:
        stack = [first_id]
        while stack:
            cur = stack.pop()
            if cur in reachable:
                continue
            reachable.add(cur)
            for nxt in adj.get(cur, []):
                if nxt not in reachable:
                    stack.append(nxt)

    all_ids = {n["id"] for n in graph["nodes"]}
    unreachable = all_ids - reachable
    if unreachable:
        print(f"WARNING: Unreachable nodes: {unreachable}")

    print(f"Reachable nodes: {len(reachable)} / {len(all_ids)}")", "path": "/app/solution.py"}: Editing /app/solution.py

